/**
 * Dumps the cosmetic-economy parity fixtures for the Rust server (rewrite plan Phase 3:
 * "Shop seededScore/rotation and gacha are ported bit-exactly") from the TS modules in
 * `lib/cosmetics`.
 *
 *   node --import tsx scripts/oracle/dump-cosmetic-fixtures.ts [outFile] [--check]
 *
 * Writes (default `crates/server/tests/fixtures/cosmetics.json.gz`), all inputs generated by a
 * seeded mulberry32 so the content is reproducible byte for byte. Id sets are encoded as
 * `{ "mask": <hex>, "extra": [...] }`: bit `i` of the big-endian hex mask is
 * `COSMETIC_CATALOG[i]`, and ids outside the catalog are listed in `extra`.
 *
 * - `seededScore`: `seededScore(seed, id)` samples (module-private in shop.ts, so a verbatim
 *   copy of shop.ts with one appended export is loaded from a temp dir and cross-checked against
 *   the real module's exports).
 * - `shopWeek`: `getShopWeek(new Date(ms))` across week boundaries and random instants.
 * - `rotation`: `generateRotationPool` pools and `personalizeRotation` offers for several owned
 *   sets (incl. pools with unknown ids), with `legendaryEnabled`.
 * - `rollRarity` / `selectGacha`: inputs, the `rng()` values each call consumed (as integers
 *   `k`, value `k / 1_000_000`, like `randomInt(1_000_000) / 1_000_000`) and the outputs.
 * - `rewards`, `normalizeAppearance`, `planLegacyInventory`, `remapAppearance`.
 *
 * `catalogSha256` pins the exported catalog (`crates/server/data/cosmetic-catalog.json`); the
 * Rust tests refuse a fixture made from a different catalog.
 */
import { createHash } from 'node:crypto'
import { mkdtempSync, readFileSync, rmSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { gunzipSync, gzipSync } from 'node:zlib'
import { COSMETIC_CATALOG, DEFAULT_APPEARANCE, STARTER_COSMETIC_IDS } from '../../lib/cosmetics/catalog'
import { calculateOfficialRaceQuackRewards } from '../../lib/cosmetics/economy'
import { rollRarity, selectGachaResult } from '../../lib/cosmetics/gacha'
import { normalizeAppearance } from '../../lib/cosmetics/inventory'
import { LEGACY_REMAP, planLegacyInventory, remapAppearance } from '../../lib/cosmetics/legacy'
import { LEGACY_V1_COSMETICS } from '../../lib/cosmetics/legacy-v1'
import { generateRotationPool, getShopWeek, personalizeRotation } from '../../lib/cosmetics/shop'
import type { CosmeticDefinition } from '../../lib/cosmetics/types'
import { COSMETIC_SLOTS } from '../../lib/cosmetics/types'

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '../..')
const args = process.argv.slice(2)
const check = args.includes('--check')
const outFile = resolve(args.find((arg) => !arg.startsWith('--')) ?? join(repoRoot, 'crates/server/tests/fixtures/cosmetics.json.gz'))
const catalogFile = join(repoRoot, 'crates/server/data/cosmetic-catalog.json')

// ---------------------------------------------------------------------------
// Deterministic input generator (mulberry32). Only this script uses it.

class Mulberry32 {
  private state: number
  constructor(seed: number) {
    this.state = seed >>> 0
  }
  next() {
    this.state = (this.state + 0x6d2b79f5) >>> 0
    let t = this.state
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return (t ^ (t >>> 14)) >>> 0
  }
  below(n: number) {
    return this.next() % n
  }
  pick<T>(items: readonly T[]): T {
    return items[this.below(items.length)]!
  }
  subset<T>(items: readonly T[], probability: number): T[] {
    return items.filter(() => this.next() / 0x1_0000_0000 < probability)
  }
}

const gen = new Mulberry32(0xc05_7e71)

// ---------------------------------------------------------------------------
// seededScore oracle copy

async function loadSeededScore(): Promise<(seed: string, id: string) => number> {
  const shopPath = join(repoRoot, 'lib/cosmetics/shop.ts')
  const source = readFileSync(shopPath, 'utf8').replace(/from '\.\/(\w+)'/g, (_, name: string) => `from '${pathToFileURL(join(repoRoot, 'lib/cosmetics', name)).href}.ts'`)
  const dir = mkdtempSync(join(tmpdir(), 'shop-oracle-'))
  try {
    const copy = join(dir, 'shop-oracle-copy.ts')
    writeFileSync(copy, `${source}\nexport { seededScore as __oracleSeededScore }\n`)
    const oracle = (await import(pathToFileURL(copy).href)) as {
      __oracleSeededScore: (seed: string, id: string) => number
      generateRotationPool: typeof generateRotationPool
    }
    for (const [season, week] of [['S3', '2026-08-10'], ['s3', '2026-11-09']]) {
      if (JSON.stringify(oracle.generateRotationPool(season!, week!)) !== JSON.stringify(generateRotationPool(season!, week!))) {
        throw new Error('oracle copy diverges from shop.ts')
      }
    }
    return oracle.__oracleSeededScore
  } finally {
    rmSync(dir, { recursive: true, force: true })
  }
}

// ---------------------------------------------------------------------------
// Recording rng: draws k in [0, 1e6) from the generator (or a scripted list) and logs it.

function recordingRng(scripted?: number[]) {
  const used: number[] = []
  const rng = () => {
    const k = scripted && used.length < scripted.length ? scripted[used.length]! : gen.below(1_000_000)
    used.push(k)
    return k / 1_000_000
  }
  return { rng, used }
}

const ids = COSMETIC_CATALOG.map((item) => item.id)
const indexById = new Map(ids.map((id, index) => [id, index]))

/** An id set as a catalog bitmask (hex, bit i = catalog[i]) plus the ids outside the catalog. */
function encodeSet(set: Iterable<string>) {
  // BigInt() rather than 0n/1n literals: tsconfig targets ES2017 and `next build` type-checks scripts/.
  let mask = BigInt(0)
  const extra: string[] = []
  for (const id of new Set(set)) {
    const index = indexById.get(id)
    if (index === undefined) extra.push(id)
    else mask |= BigInt(1) << BigInt(index)
  }
  return { mask: mask.toString(16), extra }
}
const byRarity = (rarity: string) => COSMETIC_CATALOG.filter((item) => item.rarity === rarity).map((item) => item.id)
const RARITIES = ['common', 'uncommon', 'rare', 'epic', 'legendary'] as const
const SEASON_KEYS = ['S3', 's3', 'season-3', 'S4', 'ĐUA DZỊT 2026', '']

async function main() {
  const seededScore = await loadSeededScore()

  // seededScore -------------------------------------------------------------
  const seededScoreCases: Array<{ seed: string; id: string; score: number }> = []
  for (let index = 0; index < 2000; index += 1) {
    const seed = `${gen.pick(SEASON_KEYS)}:${gen.pick(['2026-08-10', '2026-11-09', '2027-01-04', String(gen.next())])}`
    const id = index % 7 === 0 ? gen.pick(['2026-08-10', 'zịt 🦆', '', ':']) : gen.pick(ids)
    seededScoreCases.push({ seed, id, score: seededScore(seed, id) })
  }

  // getShopWeek ---------------------------------------------------------------
  const shopWeekCases: Array<{ ms: number; weekKey: string; startsAt: string; endsAt: string }> = []
  const addWeek = (ms: number) => {
    const week = getShopWeek(new Date(ms))
    shopWeekCases.push({ ms, weekKey: week.weekKey, startsAt: week.startsAt.toISOString(), endsAt: week.endsAt.toISOString() })
  }
  const base = Date.UTC(2026, 7, 9, 17, 0, 0) // Monday 00:00 in Vietnam
  for (let hour = -30; hour <= 24 * 15; hour += 1) addWeek(base + hour * 3_600_000)
  for (const delta of [-1, 0, 1]) addWeek(base + delta)
  // Random instants from 1970 to 2106, plus a few before the epoch.
  for (let index = 0; index < 500; index += 1) addWeek(gen.next() * 1000 + gen.below(1000))
  for (let index = 0; index < 20; index += 1) addWeek(-(gen.next() * 100 + gen.below(1000)))
  for (const ms of [0, -1, 86_400_000 * 3, 951_782_400_000 /* 2000-02-29 */, 4_102_444_800_000 /* 2100-01-01 */]) addWeek(ms)

  // Rotation ------------------------------------------------------------------
  const rotationCases: Array<{
    seasonKey: string
    weekKey: string
    pool: string[]
    legendaryEnabled: boolean
    offers: Array<{ poolIds?: string[]; owned: ReturnType<typeof encodeSet>; offered: string[] }>
  }> = []
  const weekKeys: string[] = []
  for (let week = 0; week < 60; week += 1) weekKeys.push(new Date(Date.UTC(2026, 0, 5 + week * 7)).toISOString().slice(0, 10))
  for (const seasonKey of SEASON_KEYS) {
    for (const weekKey of weekKeys) {
      const pool = generateRotationPool(seasonKey, weekKey)
      const offers: Array<{ poolIds?: string[]; owned: ReturnType<typeof encodeSet>; offered: string[] }> = []
      const ownedSets: string[][] = [
        [],
        gen.subset(pool, 0.3),
        gen.subset(pool, 0.7),
        [...pool],
        gen.subset(ids, 0.5),
        [...STARTER_COSMETIC_IDS],
      ]
      const first = personalizeRotation(pool, new Set(), seasonKey, weekKey).map((item) => item.id)
      ownedSets.push(first)
      for (const owned of ownedSets) {
        offers.push({ owned: encodeSet(owned), offered: personalizeRotation(pool, new Set(owned), seasonKey, weekKey).map((item) => item.id) })
      }
      // A stored pool can hold retired ids, duplicates or a hand-edited order.
      const edited = [...pool.slice(0, 5), 'head-retired-hat', pool[0]!, ...gen.subset(ids, 0.1), ...pool.slice(5)]
      const editedOwned = gen.subset(edited, 0.2)
      offers.push({ poolIds: edited, owned: encodeSet(editedOwned), offered: personalizeRotation(edited, new Set(editedOwned), seasonKey, weekKey).map((item) => item.id) })
      rotationCases.push({ seasonKey, weekKey, pool, legendaryEnabled: seededScore(seasonKey, weekKey) / 0xffffffff < 0.3, offers })
    }
  }

  // rollRarity ------------------------------------------------------------------
  const pityStates = [
    [0, 0, 0], [4, 0, 0], [5, 0, 0], [6, 11, 0], [0, 12, 0], [5, 12, 0], [0, 0, 29], [0, 0, 30], [5, 12, 30], [9, 20, 40],
  ] as const
  const boundaryKs = [0, 1, 399_999, 400_000, 699_999, 700_000, 879_999, 880_000, 969_999, 970_000, 999_999, 100_000, 249_999, 250_000, 120_000, 400_001, 333_333, 666_667]
  const rollCases: Array<{ pity: [number, number, number]; rolls: number[]; rarity: string }> = []
  for (const [rare, epic, legendary] of pityStates) {
    for (const k of [...boundaryKs, ...Array.from({ length: 40 }, () => gen.below(1_000_000))]) {
      const { rng, used } = recordingRng([k])
      const rarity = rollRarity({ rarePity: rare, epicPity: epic, legendaryPity: legendary }, rng)
      rollCases.push({ pity: [rare, epic, legendary], rolls: used, rarity })
    }
  }

  // selectGachaResult -----------------------------------------------------------
  type GachaCase = {
    owned: ReturnType<typeof encodeSet>
    pity: [number, number, number]
    /** Catalog ids removed from COSMETIC_CATALOG (the route's override filter). */
    excluded: ReturnType<typeof encodeSet>
    rolls: number[]
    result: null | {
      rolledRarity: string
      finalItem: string
      wasDuplicate: boolean
      wasRerolled: boolean
      refundAmount: number
      pityAfter: { rarePity: number; epicPity: number; legendaryPity: number }
    }
    error: string | null
  }
  const gachaCases: GachaCase[] = []
  const ownedPatterns: Array<() => string[]> = [
    () => [],
    () => gen.subset(ids, 0.2),
    () => gen.subset(ids, 0.6),
    () => gen.subset(ids, 0.95),
    () => [...ids],
    () => byRarity(gen.pick(RARITIES)),
    () => [...byRarity('common'), ...byRarity('uncommon')],
    () => [...byRarity('legendary'), ...byRarity('epic'), ...gen.subset(byRarity('rare'), 0.9)],
    () => ids.filter((id) => !id.startsWith(gen.pick(['body', 'head', 'pet', 'aura']))),
  ]
  const excludePatterns: Array<() => string[]> = [
    () => [],
    () => [],
    () => gen.subset(ids, 0.3),
    () => byRarity(gen.pick(RARITIES)),
    () => [...byRarity('legendary'), ...byRarity('epic')],
    () => ids.filter((id) => !byRarity('common').includes(id)),
    () => [...ids],
  ]
  const scriptedRolls: Array<number[] | undefined> = [undefined, undefined, undefined, [0, 0, 0], [999_999, 999_999, 999_999], [400_000, 500_000, 999_999], [970_000, 0, 999_999]]
  for (let index = 0; index < 6000; index += 1) {
    const owned = gen.pick(ownedPatterns)()
    const excluded = gen.pick(excludePatterns)()
    const pity = gen.next() % 4 === 0 ? [...gen.pick(pityStates)] as [number, number, number] : [gen.below(7), gen.below(14), gen.below(32)] as [number, number, number]
    const { rng, used } = recordingRng(gen.pick(scriptedRolls))
    const excludedSet = new Set(excluded)
    const catalog: CosmeticDefinition[] = COSMETIC_CATALOG.filter((item) => !excludedSet.has(item.id))
    let result: GachaCase['result'] = null
    let error: string | null = null
    try {
      const selected = selectGachaResult({ ownedIds: new Set(owned), rarePity: pity[0], epicPity: pity[1], legendaryPity: pity[2], catalog }, rng)
      result = {
        rolledRarity: selected.rolledRarity,
        finalItem: selected.finalItem.id,
        wasDuplicate: selected.wasDuplicate,
        wasRerolled: selected.wasRerolled,
        refundAmount: selected.refundAmount,
        pityAfter: selected.pityAfter,
      }
    } catch (thrown) {
      error = (thrown as Error).message
    }
    gachaCases.push({ owned: encodeSet(owned), pity, excluded: encodeSet(excluded), rolls: used, result, error })
  }

  // Rewards -----------------------------------------------------------------------
  const rewardCases: Array<{ input: unknown; rewards: unknown }> = []
  for (let index = 0; index < 400; index += 1) {
    const users = Array.from({ length: 2 + gen.below(10) }, (_, user) => user + 1)
    const winner = gen.pick(users)
    const losers = gen.subset(users.filter((user) => user !== winner), 0.35)
    if (index % 5 === 0 && losers.length) losers.push(losers[0]!)
    const predictions = gen.subset(users, 0.8).map((user) => ({ predictorUserId: user, targetUserId: gen.pick(users) }))
    const perfectWeekEnabled = index % 3 === 0 ? undefined : index % 3 === 1
    const input = { winnerUserId: winner, finalLoserUserIds: losers, predictions, ...(perfectWeekEnabled === undefined ? {} : { perfectWeekEnabled }) }
    rewardCases.push({ input, rewards: calculateOfficialRaceQuackRewards(input) })
  }

  // Appearance / legacy -----------------------------------------------------------------
  const slotKeys = COSMETIC_SLOTS.map((slot) => `${slot}Id`)
  const legacyIds = Object.keys(LEGACY_V1_COSMETICS)
  const remapIds = Object.keys(LEGACY_REMAP)
  const randomAppearance = () => {
    const appearance: Record<string, unknown> = {}
    for (const key of [...slotKeys, 'exploitId', 'favoriteId']) {
      const choice = gen.below(8)
      if (choice === 0) continue
      if (choice === 1) appearance[key] = ''
      else if (choice === 2) appearance[key] = gen.below(5)
      else if (choice === 3) appearance[key] = gen.pick(remapIds)
      else if (choice === 4) appearance[key] = gen.pick(legacyIds)
      else appearance[key] = gen.pick(ids)
    }
    return appearance
  }
  const normalizeCases: Array<{ input: Record<string, unknown>; output: Record<string, string> | null; error: string | null }> = []
  for (let index = 0; index < 300; index += 1) {
    const input = index === 0 ? { ...DEFAULT_APPEARANCE, exploitId: 'legendary-free' } : randomAppearance()
    try {
      normalizeCases.push({ input, output: normalizeAppearance(input), error: null })
    } catch (thrown) {
      normalizeCases.push({ input, output: null, error: (thrown as Error).message })
    }
  }
  const planCases: Array<{ owned: string[]; plan: unknown }> = []
  for (let index = 0; index < 300; index += 1) {
    const owned = [...new Set([...gen.subset(legacyIds, 0.15), ...gen.subset(ids, 0.15), ...gen.subset(remapIds, 0.3), ...(index % 4 === 0 ? ['not-a-cosmetic'] : [])])]
    for (let swap = owned.length - 1; swap > 0; swap -= 1) {
      const other = gen.below(swap + 1)
      ;[owned[swap], owned[other]] = [owned[other]!, owned[swap]!]
    }
    planCases.push({ owned, plan: planLegacyInventory(owned) })
  }
  const remapCases: Array<{ appearance: Record<string, unknown>; owned: ReturnType<typeof encodeSet>; output: Record<string, string> }> = []
  for (let index = 0; index < 300; index += 1) {
    const appearance = randomAppearance()
    const owned = [...gen.subset(ids, 0.5), ...Object.values(appearance).filter((value): value is string => typeof value === 'string' && gen.next() % 2 === 0), ...gen.subset(Object.values(LEGACY_REMAP), 0.5)]
    remapCases.push({ appearance, owned: encodeSet(owned), output: remapAppearance(appearance, new Set(owned)) })
  }

  const catalogText = readFileSync(catalogFile, 'utf8')
  const exported = JSON.parse(catalogText) as { items: unknown[] }
  if (JSON.stringify(exported.items) !== JSON.stringify(COSMETIC_CATALOG)) {
    throw new Error('crates/server/data/cosmetic-catalog.json is stale: run pnpm cosmetics:export-catalog first')
  }

  const fixture = {
    format: 'autoduck-cosmetic-fixtures/1',
    generator: 'scripts/oracle/dump-cosmetic-fixtures.ts (mulberry32 0xc057e71)',
    catalogSha256: createHash('sha256').update(catalogText).digest('hex'),
    seededScore: seededScoreCases,
    shopWeek: shopWeekCases,
    rotation: rotationCases,
    rollRarity: rollCases,
    selectGacha: gachaCases,
    rewards: rewardCases,
    normalizeAppearance: normalizeCases,
    planLegacyInventory: planCases,
    remapAppearance: remapCases,
  }
  const text = `${JSON.stringify(fixture)}\n`
  if (check) {
    const current = existsSync(outFile) ? gunzipSync(readFileSync(outFile)).toString('utf8') : null
    if (current !== text) {
      console.error(`stale: ${outFile} (run node --import tsx scripts/oracle/dump-cosmetic-fixtures.ts)`)
      process.exit(1)
    }
    console.log(`up to date: ${outFile}`)
    return
  }
  mkdirSync(dirname(outFile), { recursive: true })
  const gzipped = gzipSync(Buffer.from(text, 'utf8'), { level: 9 })
  writeFileSync(outFile, gzipped)
  console.log(`wrote ${outFile} (${gzipped.length} bytes gzipped, ${text.length} raw): ${seededScoreCases.length} seededScore, ${shopWeekCases.length} shopWeek, ${rotationCases.length} rotation, ${rollCases.length} rollRarity, ${gachaCases.length} selectGacha, ${rewardCases.length} rewards, ${normalizeCases.length} normalize, ${planCases.length} plan, ${remapCases.length} remap`)
}

main().catch((error) => {
  console.error(error)
  process.exit(1)
})
